sourceCallsites.argumentsSignature:
"/api/board/chat/stream", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            companyId: selectedCompanyId,
            message: trimmed,
            taskId: boardIssueId ?? undefined,
          }),
          signal: controller.signal,
        }

companyId!, {
        mode: next.mode,
        allowedAgentIds: next.mode === "allowlist" ? next.allowedAgentIds : [],
      }

issueId, input.interaction.id, {
        selectedClientKeys: input.selectedClientKeys,
        selectedOptionIds: input.selectedOptionIds,
        rememberAction: input.rememberAction,
      }

createdCompanyId, buildOnboardingIssuePayload({
            title: DEFAULT_TASK_TITLE,
            assigneeAgentId: createdAgentId,
            projectId,
            goalId
          })

issueId!, {
        mode,
        reason: null,
        releasePolicy: {
          strategy: "manual",
          ...(mode === "pause"
            ? {
                note: scope === "leaf" ? "leaf_pause" : "full_pause",
              }
            : {}),
        },
        ...(runId
          ? { metadata: { source: "issue_active_run_control", runId } }
          : {}),
        ...(mode === "restore" ? { metadata: { wakeAgents } } : {}),
      }

entry.id, {
          mode: "pause",
          reason: "Paused from Recent Tasks.",
          releasePolicy: { strategy: "manual" },
        }

issueId, {
        action,
        note: note.trim() ? note.trim() : undefined,
      }

issueId!, pauseHoldId, {
            reason: null,
            metadata: {
              wakeAgents,
            },
          }

entry.id, state.activePauseHold.holdId, {
          reason: "Restarted from Recent Tasks.",
        }

issueId, {
        actionId: recoveryAction.id,
        outcome: data.outcome,
        sourceIssueStatus: data.sourceIssueStatus,
      }

issueId, {
        actionId: recoveryAction.id,
        outcome: "restored",
        sourceIssueStatus: "todo",
        executionReconciliation: {
          runId: descriptor.sourceRunId!,
          providerStopped: true,
          actionOutcome: input.actionOutcome,
          outcomeEvidence: input.outcomeEvidence,
          workspaceReconstruction: {
            confirmed: true,
            destructionReceiptHash: descriptor.destruction.receiptHash,
            selectedSources: descriptor.sources.filter(source => input.sourceIds.includes(source.attachmentId))
              .map(source => ({ attachmentId: source.attachmentId, sha256: source.sha256 })),
          },
        },
      }

conversationIssueId, {
        comment: body,
        assigneeAgentId: reassignment.assigneeAgentId,
        assigneeUserId: reassignment.assigneeUserId,
        ...(reopen ? { status: "todo" } : {}),
      }

await resolveWritableIssueId(), key, {
        title: key === "plan" ? null : nextTitle,
        format: "markdown",
        body,
        baseRevisionId: existing?.latestRevisionId ?? null,
      }

issue.id, stagedFile.documentKey ?? "document", {
              title: stagedFile.documentKey === "plan" ? null : stagedFile.title ?? null,
              format: "markdown",
              body,
              baseRevisionId: null,
            }

selectedCompanyId!, {
          key: baseKey,
          name: data.name,
          description: data.description || null,
        }

selectedCompanyId!, {
            key: `${baseKey}-${Date.now().toString(36)}`,
            name: data.name,
            description: data.description || null,
          }

pipelineId, {
        key: nextStageKey("New stage", existingKeys),
        name: "New stage",
        kind: "working",
        position: insertPosition,
        config: {
          variables: [],
          requireChildrenTerminal: true,
          ...(autoAdvanceTarget ? { autoAdvanceOnChildrenTerminal: autoAdvanceTarget.key } : {}),
        },
      }

row.caseId, {
          suggestionId: row.suggestionId,
          resolution: decision === "approve" ? "accept" : "dismiss",
          expectedVersion: row.expectedVersion ?? undefined,
          reason: note || null,
        }

row.caseId, {
            suggestionId: row.suggestionId!,
            resolution: "accept",
            expectedVersion: row.expectedVersion ?? undefined,
          }

caseId, {
      scope: "current_stage",
      expectedVersion: retryPlan.data?.caseVersion ?? detail?.case.version ?? 1,
      cleanup: retryCleanupFromIds(selectedRetryCleanupIds),
    }

caseId, {
      scope: plan.scope,
      targetStageId: plan.targetStage?.id ?? null,
      expectedVersion: plan.caseVersion,
      cleanup: retryCleanupFromIds(selectedRetryCleanupIds),
    }

caseId, {
        decision,
        reason: reviewDecisionNote.trim() || null,
        expectedVersion: detail.case.version,
      }

row.caseId, {
        decision: decision === "request_changes" ? "request_changes" : "approve",
        reason: note || null,
        expectedVersion: row.expectedVersion,
      }

caseId, {
        toStageKey: selectedMoveStage.key,
        expectedVersion: detail.case.version,
        reason: `Manual board override from item page: moved from ${detail.stage.name} to ${selectedMoveStage.name}.`,
        force: true,
      }

caseId, {
        toStageKey: removeStage.key,
        expectedVersion: detail.case.version,
        reason: "Removed from the item detail page.",
      }

pipelineId!, {
        name: pipelineName.trim(),
        description: pipelineDescription.trim() || null,
      }

pipelineId, selectedStage.id, {
        name: stageName.trim(),
        kind: stageKind,
        config,
      }

caseId, BODY_DOCUMENT_KEY, {
        body: input.body,
        baseRevisionId: input.baseRevisionId,
        changeSummary: input.changeSummary ?? null,
      }

pluginId, companyId, declaration.folderKey, {
        path,
        access: declaration.access,
        requiredDirectories: declaration.requiredDirectories,
        requiredFiles: declaration.requiredFiles,
      }
